CREATE FUNCTION "erp_regulatory_commands"."import_einvoice_rule_release"(p_release_id uuid, p_ruleset_version varchar, p_source_authority text, p_source_uri text, p_source_storage_bucket text, p_source_storage_object_path text, p_source_media_type varchar, p_source_bytes bytea, p_source_sha256 bytea, p_dataset_storage_bucket text, p_dataset_storage_object_path text, p_dataset_bytes bytea, p_dataset_sha256 bytea, p_publication_date date, p_effective_from date, p_effective_to date, p_reviewed_by_user_id uuid, p_reviewed_at timestamptz, p_request_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
#variable_conflict use_variable
DECLARE prior_id uuid; item jsonb; supplied_count integer; dataset_rows jsonb;
BEGIN
  IF p_request_id IS NULL OR NULLIF(pg_catalog.current_setting('app.request_id',true),'')::uuid IS DISTINCT FROM p_request_id THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='einvoice_rules import requires matching transaction-local request id';
  END IF;
  dataset_rows:=pg_catalog.convert_from(p_dataset_bytes,'UTF8')::jsonb;
  prior_id:="erp_regulatory_commands"."stage_release"(p_release_id,'einvoice_rules',p_ruleset_version,
    p_source_authority,p_source_uri,p_source_storage_bucket,p_source_storage_object_path,
