    p_effective_from,p_effective_to,p_reviewed_by_user_id,p_reviewed_at);
  supplied_count:=pg_catalog.jsonb_array_length(dataset_rows);
  IF EXISTS (
    SELECT 1 FROM pg_catalog.jsonb_array_elements(dataset_rows) AS row(value)
     WHERE pg_catalog.jsonb_typeof(value)<>'object'
        OR NOT value ?& ARRAY['id','rule_code','rule_version','organization_person_type','organization_exemption_code','registration_type','document_class','supply_scope','minimum_prior_fy_turnover','reporting_window_days','effective_from','effective_to']
        OR value - ARRAY['id','rule_code','rule_version','organization_person_type','organization_exemption_code','registration_type','document_class','supply_scope','minimum_prior_fy_turnover','reporting_window_days','effective_from','effective_to'] <> '{}'::jsonb
        OR pg_catalog.btrim(value->>'rule_code')=''
        OR pg_catalog.btrim(value->>'rule_version')=''
        OR (value->>'effective_from')::date<p_effective_from
        OR (p_effective_to IS NOT NULL AND COALESCE(NULLIF(value->>'effective_to','')::date,p_effective_to)>p_effective_to)
  ) OR (SELECT count(DISTINCT value->>'id') FROM pg_catalog.jsonb_array_elements(dataset_rows))<>supplied_count
    OR (SELECT count(DISTINCT (value->>'rule_code',value->>'rule_version')) FROM pg_catalog.jsonb_array_elements(dataset_rows))<>supplied_count
    OR EXISTS (
      SELECT 1
        FROM pg_catalog.jsonb_array_elements(dataset_rows) WITH ORDINALITY AS left_row(value,ordinality)
        JOIN pg_catalog.jsonb_array_elements(dataset_rows) WITH ORDINALITY AS right_row(value,ordinality)
          ON left_row.ordinality<right_row.ordinality
       WHERE left_row.value->>'organization_person_type'=right_row.value->>'organization_person_type' AND left_row.value->>'organization_exemption_code'=right_row.value->>'organization_exemption_code' AND left_row.value->>'registration_type'=right_row.value->>'registration_type' AND left_row.value->>'document_class'=right_row.value->>'document_class' AND left_row.value->>'supply_scope'=right_row.value->>'supply_scope'
         AND (left_row.value->>'effective_from')::date<=COALESCE(NULLIF(right_row.value->>'effective_to','')::date,'infinity'::date)
         AND (right_row.value->>'effective_from')::date<=COALESCE(NULLIF(left_row.value->>'effective_to','')::date,'infinity'::date)
    ) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='einvoice_rules dataset is not one exact non-overlapping typed set';
  END IF;
  IF prior_id IS NOT NULL THEN UPDATE tax.einvoice_rule_versions SET status='retired' WHERE release_id=prior_id AND status='active'; END IF;
  FOR item IN SELECT value FROM pg_catalog.jsonb_array_elements(dataset_rows) ORDER BY value->>'id' LOOP
    INSERT INTO tax.einvoice_rule_versions(id,release_id,rule_code,rule_version,organization_person_type,organization_exemption_code,registration_type,document_class,supply_scope,minimum_prior_fy_turnover,reporting_window_days,effective_from,effective_to,status) VALUES((item->>'id')::uuid,p_release_id,item->>'rule_code',item->>'rule_version',item->>'organization_person_type',item->>'organization_exemption_code',item->>'registration_type',item->>'document_class',item->>'supply_scope',(item->>'minimum_prior_fy_turnover')::numeric,NULLIF(item->>'reporting_window_days','')::integer,(item->>'effective_from')::date,NULLIF(item->>'effective_to','')::date,'active');
  END LOOP;
  IF (SELECT count(*) FROM tax.einvoice_rule_versions WHERE release_id=p_release_id)<>supplied_count THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='einvoice_rules exact-set count mismatch';
  END IF;
  PERFORM "erp_regulatory_commands"."finish_release"(p_release_id,prior_id);
  RETURN p_release_id;
END
$function$

